void Vbuffer::build_modifiers(std::string &out) const {
  auto *inst = &inst_;
  (void)inst;
  amdgpu::Gfx12TemporalHintKind hint_kind = amdgpu::Gfx12TemporalHintKind::Load;
  switch (inst->op) {
  case 51:
  case 52:
  case 53:
  case 54:
  case 55:
  case 56:
  case 57:
  case 58:
  case 59:
  case 60:
  case 61:
  case 62:
  case 63:
  case 64:
  case 65:
  case 66:
  case 67:
  case 68:
  case 69:
  case 70:
  case 71:
  case 72:
  case 73:
  case 74:
  case 75:
  case 76:
  case 77:
  case 80:
  case 81:
  case 82:
  case 85:
  case 86:
  case 89:
  case 90:
  case 91:
  case 92:
    hint_kind = amdgpu::Gfx12TemporalHintKind::Atomic;
    break;
  case 24:
  case 25:
  case 26:
  case 27:
  case 28:
  case 29:
  case 36:
  case 37:
    hint_kind = amdgpu::Gfx12TemporalHintKind::Store;
    break;
  default:
    break;
  }
  amdgpu::append_gfx12_cache_policy(out, inst->th, inst->scope, hint_kind);
  if (inst->offen)
    out += " offen";
  if (inst->idxen)
    out += " idxen";
  if (inst->ioffset)
    out += " offset:" + std::to_string(inst->ioffset);
  if (inst->nv)
    out += " nv";
}

