bool Vop3SdstEnc::has_encoded_dpp() const {
  if (!(inst_.src0 == amdgpu::SRC_DPP))
    return false;
  return (inst_.op >= 288 && inst_.op <= 290) || (inst_.op >= 765 && inst_.op <= 770);
}

bool Vop3SdstEnc::has_encoded_dpp8() const {
  if (!(amdgpu::dpp::is_src_dpp8(inst_.src0)))
    return false;
  return (inst_.op >= 288 && inst_.op <= 290) || (inst_.op >= 768 && inst_.op <= 770);
}

void Vop3SdstEnc::append_mnemonic(std::string &out) const {
  out += mnemonic_;
  if (has_encoded_dpp() || has_encoded_dpp8())
    out += "_e64_dpp";
}

uint32_t Vop3SdstEnc::vop3_encoded_source_count() const {
  uint32_t count = 0;
  for (uint8_t src = 0; src < num_src_; ++src) {
    if (src_operands_[src]->is_fieldless())
      continue;
    bool repeats_dst = false;
    for (uint8_t dst = 0; dst < num_dst_; ++dst)
      repeats_dst |= src_operands_[src] == dst_operands_[dst];
    if (!repeats_dst)
      ++count;
  }
  return count;
}

int32_t Vop3SdstEnc::vop3_encoded_source_index(uint8_t operand_index) const {
  int32_t encoded_index = 0;
  for (uint8_t src = 0; src <= operand_index; ++src) {
    if (src_operands_[src]->is_fieldless())
      continue;
    bool repeats_dst = false;
    for (uint8_t dst = 0; dst < num_dst_; ++dst)
      repeats_dst |= src_operands_[src] == dst_operands_[dst];
    if (repeats_dst) {
      if (src == operand_index)
        return -1;
      continue;
    }
    if (src == operand_index)
      return encoded_index;
    ++encoded_index;
  }
  return -1;
}

Vop3SdstEnc::Vop3SdstEnc(std::string_view mnemonic, const Vop3SdstEncMachineInst *inst,
                         ExecuteFn exec_fn, LiteralSupport literal_support, int num_encoded_sources)
    : IsaInstruction<Isa>(mnemonic, exec_fn), inst_(*inst) {
  size_ = sizeof(OpEncoding);
  raw_encoding_ = reinterpret_cast<const uint32_t *>(&inst_);
  encoding_id_ = raw_encoding_[0] >> 23;
  opcode_ = inst_.op;
  if (!supports_literal(literal_support, LiteralSupport::Literal32) &&
      ((num_encoded_sources > 0 && inst_.src0 == 255) ||
       (num_encoded_sources > 1 && inst_.src1 == 255) ||
       (num_encoded_sources > 2 && inst_.src2 == 255)))
    throw util::InvalidInst(std::string(mnemonic) + " does not support 32-bit literals", "");
  if (!supports_literal(literal_support, LiteralSupport::Literal64) &&
      ((num_encoded_sources > 0 && inst_.src0 == 254) ||
       (num_encoded_sources > 1 && inst_.src1 == 254) ||
       (num_encoded_sources > 2 && inst_.src2 == 254)))
    throw util::InvalidInst(std::string(mnemonic) + " does not support 64-bit literals", "");
  if ((has_encoded_dpp() || has_encoded_dpp8()) &&
      (inst_.src0 == 255 || inst_.src1 == 255 || inst_.src2 == 255))
    throw util::InvalidInst("DPP and literal operands cannot be combined", "");
  if (has_lit_0() || has_lit_1() || has_lit_0_and_has_lit_1() || has_lit_2() ||
      has_lit_0_and_has_lit_2() || has_lit_1_and_has_lit_2() ||
      has_lit_0_and_has_lit_1_and_has_lit_2())
    size_ += sizeof(MachineInst);
  if (has_encoded_dpp() || has_encoded_dpp8())
    size_ += sizeof(MachineInst);
  std::memcpy(raw_words_.data(), inst, size_);
  raw_encoding_ = raw_words_.data();
}

void Vop3SdstEnc::build_modifiers(std::string &out) const {
  auto *inst = &inst_;
  (void)inst;
  amdgpu::vop::append_vop3_disassembly(out, 0, inst->clamp, inst->omod, vop3_encoded_source_count(),
                                       false);
  if (has_encoded_dpp())
    amdgpu::dpp::append_dpp16_disassembly(out, dpp_ctrl_, dpp_row_mask_, dpp_bank_mask_,
                                          dpp_bound_ctrl_, dpp_fi_, true,
                                          amdgpu::dpp::DppCtrlDialect::Gfx10Plus);
  if (has_encoded_dpp8())
    amdgpu::dpp::append_dpp8_disassembly(out, dpp8_lane_sel_, dpp_fi_);
}

void Vop3SdstEnc::implicit_uses(RegisterSet &uses) const {
  bool dpp_partial = inst_.src0 == amdgpu::SRC_DPP &&
                     (dpp_row_mask_ != 0xF || dpp_bank_mask_ != 0xF ||
                      (dpp_bound_ctrl_ == 0 && amdgpu::dpp::dpp_ctrl_produces_oob(dpp_ctrl_)));
  if (dpp_partial)
    for (int i = 0; i < num_dst_operands(); ++i)
      if (const auto *dst = dst_operand(i))
        if (auto ref = dst->to_register_ref())
          if (ref->cls == RegClass::VGPR)
            uses.expand(*ref);
}

void Vop3SdstEnc::implicit_use_operands(std::vector<const ::rocjitsu::Operand *> &operands) const {
  bool dpp_partial = inst_.src0 == amdgpu::SRC_DPP &&
                     (dpp_row_mask_ != 0xF || dpp_bank_mask_ != 0xF ||
                      (dpp_bound_ctrl_ == 0 && amdgpu::dpp::dpp_ctrl_produces_oob(dpp_ctrl_)));
  if (dpp_partial)
    for (int i = 0; i < num_dst_operands(); ++i)
      if (const auto *dst = dst_operand(i))
        if (auto ref = dst->to_register_ref())
          if (ref->cls == RegClass::VGPR)
            operands.push_back(dst);
}

void Vop3SdstEnc::append_src_operand(std::string &out, uint8_t operand_index) const {
  const Operand *operand = src_operands_[operand_index];
  const int32_t modifier_index = vop3_encoded_source_index(operand_index);
  const auto reg = operand->to_register_ref();
  const bool half_width = modifier_index >= 0 && false && operand->size_bits() == 16 && reg &&
                          reg->cls == RegClass::VGPR;
  if (modifier_index < 0) {
    out += operand->name();
    return;
  }
  amdgpu::vop::append_vop3_operand(out, operand->name(), (0 >> modifier_index) & 1,
                                   (inst_.neg >> modifier_index) & 1, half_width,
                                   (0 >> modifier_index) & 1);
}

void Vop3SdstEnc::append_dst_operand(std::string &out, uint8_t operand_index) const {
  const Operand *operand = dst_operands_[operand_index];
  const auto reg = operand->to_register_ref();
  const bool half_width = false && operand->size_bits() == 16 && reg && reg->cls == RegClass::VGPR;
  amdgpu::vop::append_vop3_operand(out, operand->name(), false, false, half_width, (0 >> 3) & 1);
}

bool Vop3SdstEnc::has_lit_0() {
  return (((inst_.src0 == 255) && (inst_.src1 != 255)) && (inst_.src2 != 255));
}

bool Vop3SdstEnc::has_lit_1() {
  return (((inst_.src0 != 250 && inst_.src0 != 233 && inst_.src0 != 234 && inst_.src0 != 255) &&
           (inst_.src1 == 255)) &&
          (inst_.src2 != 255));
}

bool Vop3SdstEnc::has_lit_0_and_has_lit_1() {
  return (((inst_.src0 == 255) && (inst_.src1 == 255)) && (inst_.src2 != 255));
}

bool Vop3SdstEnc::has_lit_2() {
  return (((inst_.src0 != 250 && inst_.src0 != 233 && inst_.src0 != 234 && inst_.src0 != 255) &&
           (inst_.src1 != 255)) &&
          (inst_.src2 == 255));
}

bool Vop3SdstEnc::has_lit_0_and_has_lit_2() {
  return (((inst_.src0 == 255) && (inst_.src1 != 255)) && (inst_.src2 == 255));
}

bool Vop3SdstEnc::has_lit_1_and_has_lit_2() {
  return (((inst_.src0 != 250 && inst_.src0 != 233 && inst_.src0 != 234 && inst_.src0 != 255) &&
           (inst_.src1 == 255)) &&
          (inst_.src2 == 255));
}

bool Vop3SdstEnc::has_lit_0_and_has_lit_1_and_has_lit_2() {
  return (((inst_.src0 == 255) && (inst_.src1 == 255)) && (inst_.src2 == 255));
}

bool Vop3SdstEnc::has_dpp8() {
  return (((inst_.src0 == 233 || inst_.src0 == 234) && (inst_.src1 != 255)) && (inst_.src2 != 255));
}

bool Vop3SdstEnc::has_dpp16() {
  return (((inst_.src0 == 250) && (inst_.src1 != 255)) && (inst_.src2 != 255));
}

